CREATE TABLE standard_departure_staff(departure_id TEXT PRIMARY KEY REFERENCES departures(id),operator_id TEXT NOT NULL REFERENCES operators(id),employee_id TEXT NOT NULL REFERENCES premium_employees(id),responsible_name TEXT NOT NULL,assigned_by TEXT NOT NULL REFERENCES users(id),assigned_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TRIGGER standard_departure_staff_scope BEFORE INSERT ON standard_departure_staff WHEN NOT EXISTS(SELECT 1 FROM departures d JOIN route_offers r ON r.id=d.offer_id JOIN premium_employees e ON e.id=NEW.employee_id WHERE d.id=NEW.departure_id AND r.operator_id=NEW.operator_id AND e.operator_id=NEW.operator_id AND e.status='active') BEGIN SELECT RAISE(ABORT,'trip_staff_scope'); END;
CREATE TRIGGER standard_departure_staff_conflict BEFORE INSERT ON standard_departure_staff WHEN EXISTS(SELECT 1 FROM standard_departure_staff old JOIN standard_vehicle_slots os ON os.departure_id=old.departure_id AND os.active=1 JOIN standard_vehicle_slots ns ON ns.departure_id=NEW.departure_id AND ns.active=1 WHERE old.employee_id=NEW.employee_id AND old.departure_id<>NEW.departure_id AND os.starts_at<ns.ends_at AND os.ends_at>ns.starts_at) BEGIN SELECT RAISE(ABORT,'trip_staff_conflict'); END;
INSERT OR IGNORE INTO schema_migrations(version) VALUES('0032_trip_responsible');
